import {sqliteTable,text,integer,real,index,primaryKey,uniqueIndex} from 'drizzle-orm/sqlite-core';

// ── Tenancy ──────────────────────────────────────────────────────────────────
// Every company is a tenant. All business tables carry tenant_id and every
// server query filters by the signed-in member's tenant.
export const tenants=sqliteTable('tenants',{id:text('id').primaryKey(),slug:text('slug').notNull().unique(),name:text('name').notNull(),legalName:text('legal_name').notNull().default(''),domains:text('domains').notNull().default(''),status:text('status').notNull().default('active'),plan:text('plan').notNull().default('business'),brandColor:text('brand_color').notNull().default('#6D5EF8'),currency:text('currency').notNull().default('GHS'),timezone:text('timezone').notNull().default('Africa/Accra'),settingsJson:text('settings_json').notNull().default('{}'),createdAt:text('created_at').notNull()});

export const members=sqliteTable('members',{id:text('id').primaryKey(),name:text('name').notNull(),email:text('email').notNull(),role:text('role',{enum:['admin','manager','employee','viewer']}).notNull(),department:text('department').notNull(),active:integer('active').notNull().default(1),createdAt:text('created_at').notNull(),tenantId:text('tenant_id').notNull().default('procus'),phone:text('phone').notNull().default(''),title:text('title').notNull().default(''),managerId:text('manager_id'),location:text('location').notNull().default(''),roleId:text('role_id'),employeeCode:text('employee_code').notNull().default(''),platformRole:text('platform_role'),lastSeenAt:text('last_seen_at'),notifyEmail:integer('notify_email').notNull().default(1),identityId:text('identity_id'),additionalLocations:text('additional_locations').notNull().default('[]'),invitedAt:text('invited_at'),updatedAt:text('updated_at'),updatedBy:text('updated_by'),preferencesJson:text('preferences_json').notNull().default('{}')},t=>[index('members_tenant').on(t.tenantId,t.name),index('members_identity').on(t.identityId)]);
export const records=sqliteTable('records',{id:text('id').primaryKey(),module:text('module').notNull(),title:text('title').notNull(),department:text('department').notNull(),status:text('status').notNull(),owner:text('owner').notNull(),amount:real('amount').notNull().default(0),details:text('details').notNull().default(''),updated:text('updated').notNull(),version:integer('version').notNull().default(1),createdBy:text('created_by').notNull().references(()=>members.id),fileKey:text('file_key'),tenantId:text('tenant_id').notNull().default('procus')},t=>[index('idx_records_department_module').on(t.department,t.module),index('idx_records_creator').on(t.createdBy),index('records_tenant').on(t.tenantId,t.module)]);
export const audit=sqliteTable('audit',{id:text('id').primaryKey(),action:text('action').notNull(),actor:text('actor').notNull(),recordId:text('record_id').notNull(),department:text('department').notNull(),before:text('before_json'),after:text('after_json'),createdAt:text('created_at').notNull(),tenantId:text('tenant_id').notNull().default('procus'),supportSessionId:text('support_session_id')},t=>[index('idx_audit_department_time').on(t.department,t.createdAt),index('audit_tenant_time').on(t.tenantId,t.createdAt),index('audit_tenant_record').on(t.tenantId,t.recordId)]);
export const sessions=sqliteTable('sessions',{tokenHash:text('token_hash').primaryKey(),memberId:text('member_id').notNull().references(()=>members.id),expires:integer('expires').notNull(),identityId:text('identity_id'),supportSessionId:text('support_session_id')});
export const authFlows=sqliteTable('auth_flows',{state:text('state').primaryKey(),verifier:text('verifier').notNull(),nonce:text('nonce').notNull(),expires:integer('expires').notNull()});
export const importBatches=sqliteTable('import_batches',{id:text('id').primaryKey(),source:text('source').notNull(),dataset:text('dataset').notNull(),filename:text('filename').notNull(),sha256:text('sha256').notNull(),importedAt:text('imported_at').notNull(),rowCount:integer('row_count').notNull(),headersJson:text('headers_json').notNull(),tenantId:text('tenant_id').notNull().default('procus')});
export const sourceRows=sqliteTable('source_rows',{id:text('id').primaryKey(),batchId:text('batch_id').notNull().references(()=>importBatches.id),sourceKey:text('source_key'),sheet:text('sheet').notNull(),rowNumber:integer('row_number').notNull(),payloadJson:text('payload_json').notNull()},t=>[index('source_rows_batch').on(t.batchId),uniqueIndex('source_rows_position').on(t.batchId,t.sheet,t.rowNumber)]);
export const sourceLinks=sqliteTable('links',{fromId:text('from_id').notNull().references(()=>sourceRows.id),toId:text('to_id').notNull().references(()=>sourceRows.id),kind:text('kind').notNull()},t=>[primaryKey({columns:[t.fromId,t.toId,t.kind]})]);
export const qualityIssues=sqliteTable('quality_issues',{id:text('id').primaryKey(),batchId:text('batch_id').notNull(),kind:text('kind').notNull(),detailJson:text('detail_json').notNull()});
export const passwords=sqliteTable('passwords',{memberId:text('member_id').primaryKey().references(()=>members.id),username:text('username').notNull().unique(),salt:text('salt').notNull(),hash:text('password_hash').notNull(),iterations:integer('iterations').notNull(),mustChange:integer('must_change').notNull().default(1)});
