export const itNvrs=sqliteTable('it_nvrs',{id:text('id').primaryKey(),name:text('name').notNull(),address:text('address').notNull(),location:text('location').notNull().default(''),createdBy:text('created_by').notNull(),createdAt:text('created_at').notNull(),tenantId:text('tenant_id').notNull().default('procus')},t=>[uniqueIndex('it_nvrs_address_unique').on(t.tenantId,t.address)]);
export const itNvrReadings=sqliteTable('it_nvr_readings',{id:text('id').primaryKey(),nvrId:text('nvr_id').notNull().references(()=>itNvrs.id),readingDate:text('reading_date').notNull(),diskNo:integer('disk_no').notNull(),capacityGb:real('capacity_gb').notNull(),remainingGb:real('remaining_gb').notNull(),status:text('status').notNull(),attribute:text('attribute').notNull(),storageType:text('storage_type').notNull(),notes:text('notes').notNull().default(''),recordedBy:text('recorded_by').notNull().references(()=>members.id),recordedAt:text('recorded_at').notNull()},t=>[uniqueIndex('nvr_disk_day').on(t.nvrId,t.readingDate,t.diskNo)]);

export const accessRules=sqliteTable('access_rules',{id:text('id').primaryKey(),subjectType:text('subject_type').notNull(),subjectId:text('subject_id').notNull(),department:text('department').notNull(),page:text('page').notNull(),action:text('action').notNull(),effect:text('effect').notNull(),scope:text('scope').notNull(),tenantId:text('tenant_id').notNull().default('procus')},t=>[uniqueIndex('access_rule_subject_action').on(t.tenantId,t.subjectType,t.subjectId,t.department,t.page,t.action)]);

export const researchCloudJobs=sqliteTable('research_cloud_jobs',{recordingId:text('recording_id').primaryKey().references(()=>researchRecordings.id),providerId:text('provider_id').unique(),tokenHash:text('token_hash').notNull(),state:text('state').notNull(),leaseUntil:integer('lease_until').notNull().default(0),attempts:integer('attempts').notNull().default(0)});

// ── Organisation ─────────────────────────────────────────────────────────────
export const roles=sqliteTable('roles',{id:text('id').primaryKey(),tenantId:text('tenant_id').notNull(),name:text('name').notNull(),description:text('description').notNull().default(''),base:text('base').notNull().default('employee'),permissionsJson:text('permissions_json').notNull().default('{}'),locationsJson:text('locations_json').notNull().default('[]'),defaultScreen:text('default_screen').notNull().default(''),scopeJson:text('scope_json').notNull().default('{}'),vendorAccess:integer('vendor_access').notNull().default(0),assignedOnly:integer('assigned_only').notNull().default(0),template:text('template').notNull().default('custom'),pagesJson:text('pages_json'),createdBy:text('created_by').notNull(),createdAt:text('created_at').notNull(),updatedBy:text('updated_by').notNull(),updatedAt:text('updated_at').notNull()},t=>[uniqueIndex('roles_tenant_name').on(t.tenantId,t.name)]);
