// One-time invitation / password-reset tokens. Only a SHA-256 hash of the token is stored.
export const authTokens=sqliteTable('auth_tokens',{tokenHash:text('token_hash').primaryKey(),identityId:text('identity_id').notNull().references(()=>identities.id),memberId:text('member_id'),tenantId:text('tenant_id'),purpose:text('purpose').notNull(),createdBy:text('created_by'),createdAt:text('created_at').notNull(),expires:integer('expires').notNull(),usedAt:text('used_at')},t=>[index('auth_tokens_identity').on(t.identityId,t.purpose)]);
export const supportSessions=sqliteTable('support_sessions',{id:text('id').primaryKey(),ownerIdentityId:text('owner_identity_id').notNull(),tenantId:text('tenant_id').notNull().references(()=>tenants.id),reason:text('reason').notNull(),startedAt:text('started_at').notNull(),endedAt:text('ended_at'),ip:text('ip').notNull().default(''),userAgent:text('user_agent').notNull().default('')},t=>[index('support_sessions_tenant').on(t.tenantId,t.startedAt)]);
