export const savedViews=sqliteTable('saved_views',{id:text('id').primaryKey(),tenantId:text('tenant_id').notNull(),memberId:text('member_id').notNull(),gridId:text('grid_id').notNull(),name:text('name').notNull(),stateJson:text('state_json').notNull(),createdAt:text('created_at').notNull()},t=>[index('saved_views_member').on(t.tenantId,t.memberId,t.gridId)]);

